import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 실행예산액은 품의서의 프로젝트·예산과목 본예산에 딸린 exec_budget.amount 합계
// 가정: 집행액은 해당 예산과목 commitment.amount 합계
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

// 값을 잇지 않는 고정 SQL 조각이다 (조건은 이름 붙은 파라미터로만 받는다)
const INNER_SELECT = `
  SELECT
    pr.purchase_request_id AS id,
    pr.title AS title,
    pr.budget_item_id AS bi,
    COALESCE((
      SELECT SUM(eb.amount)
      FROM exec_budget eb
      JOIN main_budget mb ON mb.main_budget_id = eb.main_budget_id
      WHERE mb.project_id = pr.project_id
        AND mb.budget_item_id = pr.budget_item_id
    ), 0) AS exec,
    COALESCE((
      SELECT SUM(bc.carryover_amount)
      FROM budget_carryover bc
      WHERE bc.project_id = pr.project_id
        AND bc.budget_item_id = pr.budget_item_id
    ), 0) AS carry,
    COALESCE((
      SELECT SUM(c.amount)
      FROM commitment c
      WHERE c.budget_item_id = pr.budget_item_id
    ), 0) AS executed
  FROM purchase_request pr
`;

const OUTER_SELECT = `
  SELECT
    s.id AS "purchaseRequestId",
    s.title AS "title",
    s.bi AS "budgetItemId",
    s.exec AS "execBudgetAmount",
    s.carry AS "carryoverAmount",
    s.exec + s.carry AS "totalBudgetAmount",
    s.executed AS "executedAmount",
    s.exec + s.carry - s.executed AS "budgetBalance"
`;

function optionalId(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  const text = String(value);
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', `${label} 값이 올바르지 않습니다.`);
  }
  return text;
}

function optionalInt(value: unknown, label: string, fallback: number): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const text = String(value);
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', `${label} 값이 올바르지 않습니다.`);
  }
  return Number(text);
}

@Controller('api/v1')
export class FnSfr02402Controller {
  @Get('/purchase-requests/budget-status')
  async listPurchaseRequestBudgetStatus(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const query = checks.queryOf(req.query);
    const projectId = optionalId(query['projectId'], '프로젝트');
    const budgetItemId = optionalId(query['budgetItemId'], '예산과목');
    const rawTitle = query['title'];
    const title = rawTitle === undefined || rawTitle === null || rawTitle === '' ? null : String(rawTitle);
    if (title !== null && title.length > 200) {
      throw new ApiError(400, 'VALIDATION_FAILED', '품의 제목은 200자 이내로 입력해 주세요.');
    }
    const page = optionalInt(query['page'], '쪽', 0);
    const size = Math.min(optionalInt(query['size'], '크기', DEFAULT_SIZE), MAX_SIZE);
    if (size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '크기는 1 이상이어야 합니다.');
    }
    return transaction(async (db) => {
      const where = `
        WHERE (CAST(:projectId AS bigint) IS NULL OR pr.project_id = CAST(:projectId AS bigint))
          AND (CAST(:budgetItemId AS bigint) IS NULL OR pr.budget_item_id = CAST(:budgetItemId AS bigint))
          AND (CAST(:title AS text) IS NULL OR pr.title LIKE '%' || CAST(:title AS text) || '%')
      `;
      const filterParams = { projectId, budgetItemId, title };
      const countRows = await db.query(
        `SELECT COUNT(*) AS "total" FROM purchase_request pr ${where}`,
        filterParams,
      );
      const total = Number(countRows[0]['total']);
      const items = await db.query(
        `${OUTER_SELECT} FROM (${INNER_SELECT} ${where}) s ORDER BY s.id DESC LIMIT :size OFFSET :offset`,
        { ...filterParams, size, offset: page * size },
      );
      return { items, page, size, total };
    });
  }

  @Get('/purchase-requests/:purchaseRequestId/budget-status')
  async getPurchaseRequestBudgetStatus(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const purchaseRequestId = req.params['purchaseRequestId'];
    if (!/^\d+$/.test(purchaseRequestId)) {
      throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `${OUTER_SELECT} FROM (${INNER_SELECT} WHERE pr.purchase_request_id = CAST(:purchaseRequestId AS bigint)) s`,
        { purchaseRequestId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }
}

