import { useState } from 'react';
import {
  call,
  useData,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Field,
  TextInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const SIZE = 20;

interface Cond {
  projectId: number | string;
  budgetItemId: number | string;
  title: string;
}

const EMPTY: Cond = { projectId: '', budgetItemId: '', title: '' };

function Detail({ id, role }: { id: number; role: string }) {
  const { data, error, loading } = useData<Row>(
    () => call('GET', `/purchase-requests/${id}/budget-status`, role),
    [id],
  );
  if (loading) {
    return <p>불러오는 중입니다.</p>;
  }
  if (error) {
    return <ErrorText text={error} />;
  }
  if (!data) {
    return <p>조회 결과가 없습니다.</p>;
  }
  return (
    <Pairs
      items={[
        ['품의서 ID', String(data.purchaseRequestId)],
        ['예산과목', <RefName table="budget_item" role={role} value={data.budgetItemId} />],
        ['실행예산액', <Num value={data.execBudgetAmount} />],
        ['이월 대상 금액', <Num value={data.carryoverAmount} />],
        ['예산총액', <Num value={data.totalBudgetAmount} />],
        ['집행액', <Num value={data.executedAmount} />],
        ['예산잔액', <Num value={data.budgetBalance} />],
      ]}
    />
  );
}

export default function FnSfr02402Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Cond>(EMPTY);
  const [applied, setApplied] = useState<Cond>(EMPTY);
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);

  const { data, error, loading } = useData<Page>(
    () =>
      call<Page>('GET', '/purchase-requests/budget-status', role, undefined, {
        projectId: applied.projectId,
        budgetItemId: applied.budgetItemId,
        title: applied.title,
        page,
        size: SIZE,
      }),
    [applied, page, role],
  );

  const rows = data ? data.items : [];
  const sum = (key: string) => rows.reduce((acc, r) => acc + Number(r[key] ?? 0), 0);

  const columns: Column[] = [
    { key: 'purchaseRequestId', label: '품의서 ID' },
    { key: 'title', label: '품의 제목' },
    { key: 'execBudgetAmount', label: '실행예산액', render: (r) => <Num value={r.execBudgetAmount} /> },
    { key: 'carryoverAmount', label: '이월 대상 금액', render: (r) => <Num value={r.carryoverAmount} /> },
    { key: 'totalBudgetAmount', label: '예산총액', render: (r) => <Num value={r.totalBudgetAmount} /> },
    { key: 'executedAmount', label: '집행액', render: (r) => <Num value={r.executedAmount} /> },
    { key: 'budgetBalance', label: '예산잔액', render: (r) => <Num value={r.budgetBalance} /> },
  ];

  const search = () => {
    setPage(0);
    setApplied(draft);
    if (rows.length === 0 && !loading && !error) {
      notify('조회 조건으로 다시 조회합니다.');
    }
  };

  const reset = () => {
    setDraft(EMPTY);
    setApplied(EMPTY);
    setPage(0);
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>예산 현황 요약</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={data ? data.total : 0} />],
            ['예산총액 (현재 쪽)', <Num value={sum('totalBudgetAmount')} />],
            ['집행액 (현재 쪽)', <Num value={sum('executedAmount')} />],
            ['예산잔액 (현재 쪽)', <Num value={sum('budgetBalance')} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>구매품의서 예산</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="프로젝트">
            <LookupSelect
              table="project"
              role={role}
              value={draft.projectId}
              onChange={(v) => setDraft({ ...draft, projectId: v })}
            />
          </Field>
          <Field label="예산과목">
            <LookupSelect
              table="budget_item"
              role={role}
              value={draft.budgetItemId}
              onChange={(v) => setDraft({ ...draft, budgetItemId: v })}
            />
          </Field>
          <Field label="품의 제목">
            <TextInput value={draft.title} onChange={(v) => setDraft({ ...draft, title: v })} />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0} />
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          columns={columns}
          rows={rows}
          empty="조회 결과가 없습니다."
          onRowClick={(r) => setSelected(Number(r.purchaseRequestId))}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {selected !== null ? (
        <Drawer title="구매품의서 예산 현황" onClose={() => setSelected(null)}>
          <Detail id={selected} role={role} />
        </Drawer>
      ) : null}
    </div>
  );
}
